// =========================================================================
// ⚙️ CONFIGURATION: DEFINE MANAGED GROUPS & THEIR ADMIN PHONE NUMBERS
// =========================================================================
// Replace with your real WhatsApp Group JID (@g.us) and your Admin phone number.
// You can add as many groups as you want!
const MANAGED_GROUPS = {
  '120363412067748618@g.us': '212673684266' // e.g. 'GROUP_JID@g.us': 'ADMIN_PHONE_NUMBER'
};

const item = $input.first().json;
const data = item.data?.messages || item.data || item;
const fromJid = data.key?.remoteJid || data.from || '';

// Silently ignore messages from non-managed groups or private chats
if (!MANAGED_GROUPS[fromJid]) {
  return [];
}

const adminPhone = MANAGED_GROUPS[fromJid];
const msgObj = data.message || {};
const rawText = (
  msgObj.conversation ||
  msgObj.extendedTextMessage?.text ||
  msgObj.imageMessage?.caption ||
  msgObj.videoMessage?.caption ||
  msgObj.documentMessage?.caption ||
  data.messageBody ||
  ''
).trim();

const messageId = data.key?.id || '';
const senderJid = data.key?.participant || data.participant || fromJid;
const senderPhone = senderJid.split('@')[0].split(':')[0];
const senderName = data.pushName || senderPhone;
const groupName = item.groupName || 'Community Group';

return [{
  json: {
    groupJid: fromJid,
    groupName,
    adminPhone,
    messageId,
    senderJid,
    senderPhone,
    senderName,
    messageText: rawText,
    timestamp: new Date().toISOString()
  }
}];

// =========================================================================
// 🛡️ ZERO-LATENCY CONTENT CLASSIFIER / JEV AI DECISION ENGINE
// =========================================================================
// Classifies messages in <1ms without latency.
// Ignores normal banter, shouting, and clean messages.
const item = $input.first().json;
const text = item.messageText || '';
const lower = text.toLowerCase();

// 1. Detect unauthorized links (web URLs, Telegram, Discord, WhatsApp group invites)
const urlRegex = /(https?:\/\/[^\s]+|www\.[^\s]+|bit\.ly\/[^\s]+|t\.me\/[^\s]+|wa\.me\/[^\s]+|chat\.whatsapp\.com\/[^\s]+|discord\.gg\/[^\s]+|[a-z0-9-]+\.(com|net|org|io|xyz|top|link|app|info|vip|club)\b)/i;
const hasLink = urlRegex.test(text);

// 2. High-risk scam keywords
const scamKeywords = [
  'airdrop', 'free crypto', 'pump signal', 'forex signals', 'guaranteed profit',
  'dm me for info', 'inbox me for details', 'double your investment'
];
const hasScam = scamKeywords.some(kw => lower.includes(kw));

// 3. Severe abusive / hate speech words
const hateWords = ['fuck', 'bitch', 'asshole', 'stfu', 'dick'];
const hasHateSpeech = hateWords.some(w => lower.includes(w));

let action = 'clean';
let reason = '';

if (hasLink || hasScam) {
  action = 'warn_link';
  reason = 'External link or promotional content shared without approval';
} else if (hasHateSpeech) {
  action = 'warn_hate';
  reason = 'Abusive or disrespectful language';
}

return [{
  json: {
    ...item,
    action,
    reason,
    isViolation: action !== 'clean'
  }
}];
